// Writes app/build_info.js with the PC name, user name and date of the build,
// it is displayed in the app About dialog.
// Run it before running/packaging the app: node release/stamp_build.js
// app/build_info.js is git ignored (app/*.js) as it is generated by this file
var fs = require('fs');
var os = require('os');
var path = require('path');

function pad(value) {
    return (value < 10 ? '0' : '') + value;
}

var now = new Date();
var date =
    now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate()) + ' ' + pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());

var info = {
    host: os.hostname(),
    user: os.userInfo().username,
    date: date
};

var file = path.join(__dirname, '..', 'app', 'build_info.js');

fs.writeFileSync(file, '//Generated by release/stamp_build.js, do not edit\nvar Main_BuildInfo = ' + JSON.stringify(info) + ';\n');

console.log('Build info written to ' + file + ': ' + info.host + '/' + info.user + ' at ' + info.date);
